import csv, math
for label,path in [('upregulation','codex_work/galaxy_outputs/gost_up.tsv'),('downregulation','codex_work/galaxy_outputs/gost_down.tsv')]:
    rows=[]
    with open(path) as f:
        for r in csv.DictReader(f, delimiter='\\t'):
            if r.get('source')=='GO:BP' and 'metabolic' in r.get('term_name','').lower():
                rows.append(r)
    print(label, 'metabolic_terms', len(rows), 'total_terms', sum(1 for _ in open(path))-1)
